/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'fs'

// Parse command line arguments
const mode = process.argv[2]
if (!['merge', 'merge2', 'regions'].includes(mode)) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
  process.exit(2)
}

// Read stdin
const input = readFileSync(0, 'utf8')
const parts = input.split('\n%%%\n')
if (parts.length !== 3) {
  process.stderr.write('error: expected three parts separated by %%%\n')
  process.exit(2)
}

// Parse documents
const [mine, base, theirs] = parts.map(part => {
  const lines = part.split('\n')
  // Drop empty tail from trailing newline
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }
  return lines
})

// Compute LCS with special tie-breaking rules
function computeLCS(side, base) {
  const n = side.length
  const m = base.length

  // dp[i][j] = length of LCS of side[0..i-1] and base[0..j-1]
  const dp = Array(n + 1).fill(null).map(() => Array(m + 1).fill(0))

  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      if (side[i - 1] === base[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
      }
    }
  }

  // Backtrack to find LCS with our specific tie-breaking rules
  const lcsIndices = { side: [], base: [] }
  let i = n
  let j = m

  while (i > 0 && j > 0) {
    if (side[i - 1] === base[j - 1]) {
      // Match found
      lcsIndices.side.unshift(i - 1)
      lcsIndices.base.unshift(j - 1)
      i--
      j--
    } else {
      // No match at current position
      // Check remaining lengths
      const remainingSide = dp[i - 1][j]
      const remainingBase = dp[i][j - 1]

      if (remainingSide >= remainingBase) {
        // Advance side (prefer side when lengths are equal, unless base is strictly longer)
        i--
      } else {
        // Advance base
        j--
      }
    }
  }

  return lcsIndices
}

// Extract changes from LCS
function getChanges(side, base, lcsIndices) {
  const changes = []
  let sideIdx = 0
  let baseIdx = 0
  let lcsIdx = 0

  while (lcsIdx < lcsIndices.side.length || sideIdx < side.length || baseIdx < base.length) {
    if (lcsIdx < lcsIndices.side.length) {
      const nextSideIdx = lcsIndices.side[lcsIdx]
      const nextBaseIdx = lcsIndices.base[lcsIdx]

      // There's a gap before this LCS match
      if (sideIdx < nextSideIdx || baseIdx < nextBaseIdx) {
        const sideStart = sideIdx
        const sideEnd = nextSideIdx
        const baseStart = baseIdx
        const baseEnd = nextBaseIdx

        changes.push({
          baseStart,
          baseEnd,
          sideStart,
          sideEnd
        })

        sideIdx = nextSideIdx
        baseIdx = nextBaseIdx
      }

      // Consume the LCS match
      sideIdx++
      baseIdx++
      lcsIdx++
    } else {
      // Remaining lines after all LCS matches
      changes.push({
        baseStart: baseIdx,
        baseEnd: base.length,
        sideStart: sideIdx,
        sideEnd: side.length
      })
      break
    }
  }

  return changes
}

// Compute changes for both sides
const mineChanges = getChanges(mine, base, computeLCS(mine, base))
const theirsChanges = getChanges(theirs, base, computeLCS(theirs, base))

// Merge changes into regions
function mergeChanges(mineChanges, theirsChanges) {
  const changes = []

  // Add all changes with their source
  for (const change of mineChanges) {
    changes.push({ ...change, from: 'mine' })
  }
  for (const change of theirsChanges) {
    changes.push({ ...change, from: 'theirs' })
  }

  // Sort by baseStart, then by source (mine before theirs)
  changes.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    return (a.from === 'mine' ? 0 : 1) - (b.from === 'mine' ? 0 : 1)
  })

  // Group overlapping changes into regions
  const regions = []
  let i = 0

  while (i < changes.length) {
    const firstChange = changes[i]
    const region = {
      baseStart: firstChange.baseStart,
      baseEnd: firstChange.baseEnd,
      changes: [firstChange]
    }

    i++

    // Keep absorbing changes that start at or before the region's current end
    while (i < changes.length && changes[i].baseStart <= region.baseEnd) {
      const change = changes[i]
      region.baseEnd = Math.max(region.baseEnd, change.baseEnd)
      region.changes.push(change)
      i++
    }

    regions.push(region)
  }

  return regions
}

const regions = mergeChanges(mineChanges, theirsChanges)

// Resolve each region
function resolveRegion(region, mine, base, theirs) {
  const mineChangesInRegion = region.changes.filter(c => c.from === 'mine')
  const theirsChangesInRegion = region.changes.filter(c => c.from === 'theirs')

  if (mineChangesInRegion.length === 0) {
    // Only theirs changed
    return {
      type: 'theirs',
      lines: theirs.slice(
        theirsChangesInRegion[0].sideStart,
        theirsChangesInRegion[theirsChangesInRegion.length - 1].sideEnd
      ),
      baseStart: region.baseStart,
      baseEnd: region.baseEnd
    }
  }

  if (theirsChangesInRegion.length === 0) {
    // Only mine changed
    return {
      type: 'mine',
      lines: mine.slice(
        mineChangesInRegion[0].sideStart,
        mineChangesInRegion[mineChangesInRegion.length - 1].sideEnd
      ),
      baseStart: region.baseStart,
      baseEnd: region.baseEnd
    }
  }

  // Both sides changed
  // Calculate replacement ranges
  const mineReplacementStart = mineChangesInRegion[0].sideStart - 
    (mineChangesInRegion[0].baseStart - region.baseStart)
  const mineReplacementEnd = mineChangesInRegion[mineChangesInRegion.length - 1].sideEnd +
    (region.baseEnd - mineChangesInRegion[mineChangesInRegion.length - 1].baseEnd)

  const theirsReplacementStart = theirsChangesInRegion[0].sideStart - 
    (theirsChangesInRegion[0].baseStart - region.baseStart)
  const theirsReplacementEnd = theirsChangesInRegion[theirsChangesInRegion.length - 1].sideEnd +
    (region.baseEnd - theirsChangesInRegion[theirsChangesInRegion.length - 1].baseEnd)

  const mineLines = mine.slice(mineReplacementStart, mineReplacementEnd)
  const baseLines = base.slice(region.baseStart, region.baseEnd)
  const theirsLines = theirs.slice(theirsReplacementStart, theirsReplacementEnd)

  // Check for conflict
  if (mineLines.length === theirsLines.length && mineLines.every((l, i) => l === theirsLines[i])) {
    // Both sides made the same change
    return {
      type: 'both',
      lines: mineLines,
      baseStart: region.baseStart,
      baseEnd: region.baseEnd
    }
  }

  if (mineLines.length === baseLines.length && mineLines.every((l, i) => l === baseLines[i])) {
    // Mine equals base, so theirs changed
    return {
      type: 'theirs',
      lines: theirsLines,
      baseStart: region.baseStart,
      baseEnd: region.baseEnd
    }
  }

  if (theirsLines.length === baseLines.length && theirsLines.every((l, i) => l === baseLines[i])) {
    // Theirs equals base, so mine changed
    return {
      type: 'mine',
      lines: mineLines,
      baseStart: region.baseStart,
      baseEnd: region.baseEnd
    }
  }

  // Actual conflict
  return {
    type: 'conflict',
    mineLines,
    baseLines,
    theirsLines,
    baseStart: region.baseStart,
    baseEnd: region.baseEnd
  }
}

// Check if there are any changes at all
if (regions.length === 0 || (regions.length === 1 && regions[0].baseStart === 0 && regions[0].baseEnd === 0)) {
  // No changes, output everything as stable
  if (mode === 'merge') {
    for (const line of base) {
      process.stdout.write(line + '\n')
    }
  } else if (mode === 'merge2') {
    for (const line of base) {
      process.stdout.write(line + '\n')
    }
  } else if (mode === 'regions') {
    if (base.length > 0) {
      process.stdout.write(`stable ${base.length}\n`)
    }
  }
  process.exit(0)
}

// Build output
let output = []
let hasConflict = false
let currentBaseIdx = 0

// Add stable regions before the first change
if (regions[0].baseStart > 0) {
  if (mode === 'regions') {
    output.push({ type: 'stable', count: regions[0].baseStart })
  } else {
    for (let i = 0; i < regions[0].baseStart; i++) {
      output.push({ type: 'line', text: base[i] })
    }
  }
  currentBaseIdx = regions[0].baseStart
}

// Process each region
for (const region of regions) {
  const resolved = resolveRegion(region, mine, base, theirs)

  if (mode === 'regions') {
    if (resolved.type === 'stable') {
      output.push({ type: 'stable', count: resolved.lines.length })
    } else if (resolved.type === 'both') {
      output.push({ type: 'both', count: resolved.lines.length })
    } else if (resolved.type === 'mine') {
      output.push({ type: 'mine', count: resolved.lines.length })
    } else if (resolved.type === 'theirs') {
      output.push({ type: 'theirs', count: resolved.lines.length })
    } else if (resolved.type === 'conflict') {
      hasConflict = true
      output.push({
        type: 'conflict',
        mineCount: resolved.mineLines.length,
        baseCount: resolved.baseLines.length,
        theirsCount: resolved.theirsLines.length
      })
    }
  } else {
    if (resolved.type === 'conflict') {
      hasConflict = true
      output.push({ type: 'conflict_start' })
      for (const line of resolved.mineLines) {
        output.push({ type: 'line', text: line })
      }
      output.push({ type: 'conflict_base' })
      for (const line of resolved.baseLines) {
        output.push({ type: 'line', text: line })
      }
      output.push({ type: 'conflict_sep' })
      for (const line of resolved.theirsLines) {
        output.push({ type: 'line', text: line })
      }
      output.push({ type: 'conflict_end' })
    } else {
      for (const line of resolved.lines) {
        output.push({ type: 'line', text: line })
      }
    }
  }

  currentBaseIdx = resolved.baseEnd || region.baseEnd
}

// Add stable regions after the last change
if (currentBaseIdx < base.length) {
  if (mode === 'regions') {
    output.push({ type: 'stable', count: base.length - currentBaseIdx })
  } else {
    for (let i = currentBaseIdx; i < base.length; i++) {
      output.push({ type: 'line', text: base[i] })
    }
  }
}

// Output
if (mode === 'merge') {
  for (const item of output) {
    if (item.type === 'line') {
      process.stdout.write(item.text + '\n')
    } else if (item.type === 'conflict_start') {
      process.stdout.write('<<<<<<< mine\n')
    } else if (item.type === 'conflict_base') {
      process.stdout.write('||||||| base\n')
    } else if (item.type === 'conflict_sep') {
      process.stdout.write('=======\n')
    } else if (item.type === 'conflict_end') {
      process.stdout.write('>>>>>>> theirs\n')
    }
  }
} else if (mode === 'merge2') {
  for (const item of output) {
    if (item.type === 'line') {
      process.stdout.write(item.text + '\n')
    } else if (item.type === 'conflict_start') {
      process.stdout.write('<<<<<<< mine\n')
    } else if (item.type === 'conflict_base') {
      // Skip base marker in merge2
    } else if (item.type === 'conflict_sep') {
      process.stdout.write('=======\n')
    } else if (item.type === 'conflict_end') {
      process.stdout.write('>>>>>>> theirs\n')
    }
  }
} else if (mode === 'regions') {
  for (const item of output) {
    if (item.type === 'stable') {
      process.stdout.write(`stable ${item.count}\n`)
    } else if (item.type === 'mine') {
      process.stdout.write(`mine ${item.count}\n`)
    } else if (item.type === 'theirs') {
      process.stdout.write(`theirs ${item.count}\n`)
    } else if (item.type === 'both') {
      process.stdout.write(`both ${item.count}\n`)
    } else if (item.type === 'conflict') {
      process.stdout.write(`conflict mine=${item.mineCount} base=${item.baseCount} theirs=${item.theirsCount}\n`)
    }
  }
}

process.exit(hasConflict ? 1 : 0)
