const input = readFileSync(0, 'utf8')
const parts = input.split('\n%%%\n')
if (parts.length !== 3) {
  process.stderr.write('error: expected three parts separated by %%%\n')
  process.exit(2)
}

// Parse documents
const [mine, base, theirs] = parts.map(part => {
  const lines = part.split('\n')
  // Drop empty tail from trailing newline
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }
  return lines
})

// Compute LCS with special tie-breaking rules
function computeLCS(side, base) {
  const n = side.length
  const m = base.length

  // dp[i][j] = length of LCS of side[0..i-1] and base[0..j-1]
  const dp = Array(n + 1).fill(null).map(() => Array(m + 1).fill(0))

  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      if (side[i - 1] === base[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
      }
    }
  }

  // Backtrack to find LCS with our specific tie-breaking rules
  const lcsIndices = { side: [], base: [] }
  let i = n
  let j = m

  while (i > 0 && j > 0) {
    if (side[i - 1] === base[j - 1]) {
      // Match found
      lcsIndices.side.unshift(i - 1)
      lcsIndices.base.unshift(j - 1)
      i--
      j--
    } else {
      // No match at current position
      // Check remaining lengths
      const remainingSide = dp[i - 1][j]
      const remainingBase = dp[i][j - 1]

      if (remainingSide >= remainingBase) {
        // Advance side (prefer side when lengths are equal, unless base is strictly longer)
        i--
      } else {
        // Advance base
        j--
      }
    }
  }

  return lcsIndices
}

// Extract changes from LCS
function getChanges(side, base, lcsIndices) {
  const changes = []
  let sideIdx = 0
  let baseIdx = 0
  let lcsIdx = 0

  while (lcsIdx < lcsIndices.side.length || sideIdx < side.length || baseIdx < base.length) {
    if (lcsIdx < lcsIndices.side.length) {
      const nextSideIdx = lcsIndices.side[lcsIdx]
      const nextBaseIdx = lcsIndices.base[lcsIdx]

      // There's a gap before this LCS match
      if (sideIdx < nextSideIdx || baseIdx < nextBaseIdx) {
        const sideStart = sideIdx
        const sideEnd = nextSideIdx
        const baseStart = baseIdx
        const baseEnd = nextBaseIdx

        changes.push({
          baseStart,
          baseEnd,
          sideStart,
          sideEnd
        })

        sideIdx = nextSideIdx
        baseIdx = nextBaseIdx
      }

      // Consume the LCS match
      sideIdx++
      baseIdx++
      lcsIdx++
    } else {
      // Remaining lines after all LCS matches
      changes.push({
        baseStart: baseIdx,
        baseEnd: base.length,
        sideStart: sideIdx,
        sideEnd: side.length
      })
      break
    }
  }

  return changes
