let hasConflict = false
let currentBaseIdx = 0

// Add stable regions before the first change
if (regions[0].baseStart > 0) {
  if (mode === 'regions') {
    output.push({ type: 'stable', count: regions[0].baseStart })
  } else {
    for (let i = 0; i < regions[0].baseStart; i++) {
