const mine = lines.slice(0, separators[0])
const base = lines.slice(separators[0] + 1, separators[1])
const theirs = lines.slice(separators[1] + 1)

// Compute LCS with specific tie-breaking rules
function computeLCS(side, base) {
  const n = side.length
  const m = base.length

  // dp[i][j] = length of LCS of side[0..i-1] and base[0..j-1]
  const dp = Array(n + 1).fill(null).map(() => Array(m + 1).fill(0))

  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      if (side[i - 1] === base[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
      }
    }
  }

  // Backtrack to find LCS with our specific tie-breaking rules
  const lcsIndices = { side: [], base: [] }
  let i = n
  let j = m

  while (i > 0 && j > 0) {
    if (side[i - 1] === base[j - 1]) {
      // Match found
      lcsIndices.side.unshift(i - 1)
      lcsIndices.base.unshift(j - 1)
      i--
      j--
    } else {
      // No match at current position
      // Check remaining lengths in LCS table
      const remainingSide = dp[i - 1][j]
      const remainingBase = dp[i][j - 1]

      if (remainingSide >= remainingBase) {
        // Advance side (prefer side when equal or longer)
        i--
      } else {
        // Advance base only when it's strictly better
        j--
      }
    }
  }

  return lcsIndices
}

// Extract changes from LCS
function getChanges(side, base, lcsIndices) {
  const changes = []
  let sideIdx = 0
  let baseIdx = 0
  let lcsIdx = 0

  while (lcsIdx < lcsIndices.side.length) {
    const nextSideIdx = lcsIndices.side[lcsIdx]
    const nextBaseIdx = lcsIndices.base[lcsIdx]

    // If there's a gap before this LCS match, it's a change
    if (sideIdx < nextSideIdx || baseIdx < nextBaseIdx) {
      changes.push({
        baseStart: baseIdx,
        baseEnd: nextBaseIdx,
        sideStart: sideIdx,
        sideEnd: nextSideIdx
      })
    }

    // Consume the LCS match
    sideIdx = nextSideIdx + 1
    baseIdx = nextBaseIdx + 1
    lcsIdx++
  }

