{"file_path":"src/merge.js","content":"/** Three-way merge of two sides against the base they both derive from. */

import { changes } from './lcs.js'

function sameLines(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * The regions of the merge, in base order: stable stretches the merge keeps
 * unchanged, and the resolutions of the stretches either side changed.
 */
export function regionsOf(mine, base, theirs) {
  const all = []
  for (const c of changes(mine, base)) all.push({ ...c, from: 'mine' })
  for (const c of changes(theirs, base)) all.push({ ...c, from: 'theirs' })
  all.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    return (a.from === 'mine' ? 0 : 1) - (b.from === 'mine' ? 0 : 1)
  })

  const groups = []
  let i = 0
  while (i < all.length) {
    const first = all[i]
    const group = { baseStart: first.baseStart, baseEnd: first.baseEnd, changes: [first] }
    i++
    while (i < all.length && all[i].baseStart <= group.baseEnd) {
      if (all[i].baseEnd > group.baseEnd) group.baseEnd = all[i].baseEnd
      group.changes.push(all[i])
      i++
    }
    groups.push(group)
  }

  const out = []
  let at = 0
  for (const group of groups) {
    if (at < group.baseStart) {
      out.push({ kind: 'stable', lines: base.slice(at, group.baseStart) })
    }
    out.push(resolve(group, mine, base, theirs))
    at = group.baseEnd
  }
  if (at < base.length) out.push({ kind: 'stable', lines: base.slice(at, base.length) })
  return out
}

/** The lines a side contributes to a region spanning more than its own change. */
function sideLines(doc, own, group) {
  let sideStart = own[0].sideStart - (own[0].baseStart - group.baseStart)
  let sideEnd = own[own.length - 1].sideEnd + (group.baseEnd - own[own.length - 1].baseEnd)
  for (const c of own) {
    const start = c.sideStart - (c.baseStart - group.baseStart)
    const end = c.sideEnd + (group.baseEnd - c.baseEnd)
    if (start < sideStart) sideStart = start
    if (end > sideEnd) sideEnd = end
  }
  return doc.slice(sideStart, sideEnd)
}

function resolve(group, mine, base, theirs) {
  if (group.changes.length === 1) {
    const only = group.changes[0]
    const doc = only.from === 'mine' ? mine : theirs
    return { kind: only.from, lines: doc.slice(only.sideStart, only.sideEnd) }
  }

  const ours = group.changes.filter(c => c.from === 'mine')
  const others = group.changes.filter(c => c.from === 'theirs')
  if (others.length === 0) return { kind: 'mine', lines: sideLines(mine, ours, group) }
  if (ours.length === 0) return { kind: 'theirs', lines: sideLines(theirs, others, group) }

  const mineLines = sideLines(mine, ours, group)
  const baseLines = base.slice(group.baseStart, group.baseEnd)
  const theirLines = sideLines(theirs, others, group)

  if (sameLines(mineLines, theirLines)) return { kind: 'both', lines: mineLines }
  if (sameLines(mineLines, baseLines)) return { kind: 'theirs', lines: theirLines }
  if (sameLines(theirLines, baseLines)) return { kind: 'mine', lines: mineLines }
  return { kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirLines }
}
"}

