{"file_path":"src/lcs.js","content":"/**
 * Longest common subsequence over whole lines, with the tie-break the
 * specification demands: walking both documents from the start, take a match
 * whenever the two current lines are equal, and otherwise advance the side
 * whose remaining subsequence is at least as long as the other's, preferring
 * to advance the base when they tie.
 */

/** Table of suffix LCS lengths: suf[i][j] = LCS(side[i..], base[j..]). */
function suffixTable(side, base) {
  const n = side.length
  const m = base.length
  const table = new Array(n + 1)
  for (let i = 0; i <= n; i++) table[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    const row = table[i]
    const next = table[i + 1]
    for (let j = m - 1; j >= 0; j--) {
      if (side[i] === base[j]) row[j] = next[j + 1] + 1
      else {
        const a = next[j]
        const b = row[j + 1]
        row[j] = a > b ? a : b
      }
    }
  }
  return table
}

/** The matched index pairs of the chosen subsequence. */
export function matches(side, base) {
  const suf = suffixTable(side, base)
  const pairs = []
  let i = 0
  let j = 0
  while (i < side.length && j < base.length) {
    if (side[i] === base[j]) {
      pairs.push([i, j])
      i++
      j++
    } else if (suf[i][j + 1] >= suf[i + 1][j]) {
      // Advancing the base leaves a subsequence at least as long: prefer it.
      j++
    } else {
      i++
    }
  }
  return pairs
}

/**
 * Every stretch the subsequence does not cover, as a run of base lines
 * replaced by a run of that side's lines.
 */
export function changes(side, base) {
  const pairs = matches(side, base)
  const result = []
  let sideAt = 0
  let baseAt = 0
  for (const [si, bj] of pairs) {
    if (sideAt < si || baseAt < bj) {
      result.push({ baseStart: baseAt, baseEnd: bj, sideStart: sideAt, sideEnd: si })
    }
    sideAt = si + 1
    baseAt = bj + 1
  }
  if (sideAt < side.length || baseAt < base.length) {
    result.push({
      baseStart: baseAt,
      baseEnd: base.length,
      sideStart: sideAt,
      sideEnd: side.length,
    })
  }
  return result
}
"}

