 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { regionsOf } from './merge.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

const argv = process.argv.slice(2)
const mode = argv[0]
if (argv.length !== 1 || (mode !== 'merge' && mode !== 'merge2' && mode !== 'regions')) {
  fail('usage: cli.js merge|merge2|regions')
} else {
  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }

  if (parts.length !== 3) {
    fail('expected three parts separated by %%%')
  } else {
    const [mine, base, theirs] = parts
    const regions = regionsOf(mine, base, theirs)
    const out = []
    let conflicted = false

    for (const region of regions) {
      if (region.kind === 'conflict') conflicted = true
      if (mode === 'regions') {
        if (region.kind === 'conflict') {
          out.push(
            `conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`,
          )
        } else {
          out.push(`${region.kind} ${region.lines.length}`)
        }
      } else if (region.kind === 'conflict') {
        out.push('<<<<<<< mine')
        for (const line of region.mine) out.push(line)
        if (mode === 'merge') {
          out.push('||||||| base')
          for (const line of region.base) out.push(line)
        }
        out.push('=======')
        for (const line of region.theirs) out.push(line)
        out.push('>>>>>>> theirs')
      } else {
        for (const line of region.lines) out.push(line)
      }
    }

    if (out.length > 0) process.stdout.write(out.map(line => `${line}\n`).join(''))
    process.exitCode = conflicted ? 1 : 0
  }
}

