/** The lines a side contributes to a region spanning more than its own change. */
function sideLines(doc, own, group) {
  // The smallest start of its own changes, moved back by however far the
  // region begins before those changes do in the base, to the largest end of
  // its own changes, moved forward by however far the region ends after them.
  let sideStart = own[0].sideStart
  let baseStart = own[0].baseStart
  let sideEnd = own[0].sideEnd
  let baseEnd = own[0].baseEnd
  for (const c of own) {
    if (c.sideStart < sideStart) sideStart = c.sideStart
    if (c.baseStart < baseStart) baseStart = c.baseStart
    if (c.sideEnd > sideEnd) sideEnd = c.sideEnd
    if (c.baseEnd > baseEnd) baseEnd = c.baseEnd
  }
  const start = sideStart - (baseStart - group.baseStart)
  const end = sideEnd + (group.baseEnd - baseEnd)
  return doc.slice(start, Math.max(start, end))
}

